import { ipcMain, ipcRenderer } from "electron";
import { ChildProcess, spawn } from "child_process";
import { randomUUID } from "crypto";

/**
 * ## Executed Process
 * Represents an program that is being executed asynchronously.
 * 
 * ### Arguments
 * - `process` : The raw `ChildProcess` class provided by the **child_process** lib from Node.JS.
 * - `uuid` : The process UUID, generated by the **Process Manager**
 * 
 * ### Functions
 * - #### `startListening()` : Begins to listen all the outputs from the program, then sends an event from IPC methods.
 * - #### `receiveListenings()` : Allows to receive commands from IPC methods, like the `kill`(process-[process-uuid]:kill).
 * - #### `kill()` : Remove all listeners and kills the process. Same process as than allowing commands.
 */
export class ExecutedProcess {
    constructor(private process: ChildProcess, public uuid: string) {}

    /**
     * ## Start Listening
     * Starts to listen to all outputs from the program, waiting for any data, then sends an event from IPC methods.
     * @returns void
     */
    public startListening() {
        this.process.stdout?.on("data", (data) => {
            ipcRenderer.send(`process-${this.uuid}:stdout`, data);
        });

        this.process.stderr?.on("data", (data) => {
            ipcRenderer.send(`process-${this.uuid}:stderr`, data);
        });
        
        this.process.on("close", (code) => {
            ipcRenderer.send(`process-${this.uuid}:died`, code);
        });
    }

    /**
     * ## Receive Listenings
     * Allows the process to receive calls, like the `kill` call.
     * @returns void
     */
    public receiveListenings() {
        ipcMain.on(`process-${this.uuid}:kill`, (_) => {
            this.kill();
        });
    }

    /**
     * ## Kill
     * Remove all the listeners, then kills the program.
     * Works the same if you allow listenings and use the `kill` call.
     * @returns void
     */
    public kill() {
        ipcMain.removeAllListeners(`process-${this.uuid}:kill`);
        this.process.kill();
    }
}

/**
 * ## Process Manager Handler
 * Handles the **renderer-side** calls to create new processes.
 * 
 * ### Arguments
 * - `verbose`: A boolean value that tells if the manager can print informations in the console.
 * 
 * ### Functions
 * - #### `register()` : Starts listening for the calls, like `executer:spawn`.
 * - #### `unregister()` : Stop listening for calls.
 */
export class ProcessManagerHandler {
    private processes = new Map<string, ExecutedProcess>();

    constructor(private verbose: boolean = false) {
        this.register();
    }

    /**
     * ## Register
     * Starts listening for the **renderer-side** calls.
     * @return void.
     */
    public register() {
        ipcMain.handle("executer:spawn", (_, command: string, args: string[]) => {
            const uuid = randomUUID();
            const rawProcess = spawn(command, args);

            const process = new ExecutedProcess(rawProcess, uuid);

            this.processes.set(uuid, process);
            process.startListening();

            return uuid;
        });

        ipcMain.handle("executer:kill", (_, uuid: string) => {
            this.processes.get(uuid)?.kill();
            this.processes.delete(uuid);
        });
    }

    /**
     * ## Unregister
     * Stop listening for calls and kill all the processes created.
     * @returns void
     */
    public unregister() {
        ipcMain.removeHandler("executer:spawn");
        ipcMain.removeHandler("executer:kill");

        for (const process of this.processes.values()) {
            process.kill();
        }

        this.processes.clear();
    }
}